var objectSchema = (toolName, required6 = [], optional3 = []) => ({
  type: "object",
  properties: Object.fromEntries([...required6, ...optional3].map((name) => [name, toolName === "craft_context_open" && (name === "max_chars" || name === "max_items") ? {
    type: "integer",
    minimum: 1,
    maximum: name === "max_chars" ? DEFAULT_CONTEXT_MAX_CHARS : DEFAULT_CONTEXT_MAX_ITEMS,
    description: `Range: 1 to ${name === "max_chars" ? DEFAULT_CONTEXT_MAX_CHARS : DEFAULT_CONTEXT_MAX_ITEMS}; omit to use the default.`
  } : ENUMS_BY_TOOL[toolName]?.[name] ? { type: "string", enum: [...ENUMS_BY_TOOL[toolName][name]] } : TYPES_BY_TOOL[toolName]?.[name] ? { type: TYPES_BY_TOOL[toolName][name] } : schemaFor(name)])),
  required: required6,
  additionalProperties: false
});
var tool = (name, description, required6 = [], readOnly = false, optional3 = []) => ({
  name,
  description,
  inputSchema: objectSchema(name, required6, optional3),
  ...readOnly ? { annotations: { readOnlyHint: true } } : {}
});

